def solve(grid):
    # Find the color that marks the bounding rectangle (the "corner" color).
    # In all given examples this is the integer 4, appearing exactly four times
    # in two distinct rows and two distinct columns.
    from collections import Counter
    positions = {}
    counts = Counter()
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v != 0:
                counts[v] += 1
                positions.setdefault(v, []).append((i, j))

    # Look for a colour with exactly 4 occurrences that occupies two rows and two columns.
    corner_color = None
    for v, lst in positions.items():
        if len(lst) == 4:
            rows = {r for r, _ in lst}
            cols = {c for _, c in lst}
            if len(rows) == 2 and len(cols) == 2:
                corner_color = v
                break

    # If for some reason no such colour is found, fall back to 4.
    if corner_color is None:
        corner_color = 4

    pts = positions[corner_color]
    min_r = min(r for r, _ in pts)
    max_r = max(r for r, _ in pts)
    min_c = min(c for _, c in pts)
    max_c = max(c for _, c in pts)

    # Crop the grid to the bounding rectangle (inclusive).
    cropped = [row[min_c:max_c + 1] for row in grid[min_r:max_r + 1]]
    return cropped

